package main import ( "bufio" "bytes" "encoding/json" "fmt" "net/http" "strings"
) func streamChat(message, token string) (string, error) { body, _ := json.Marshal(map[string]string{ "message": message, "agent_type": "research", }) req, err := http.NewRequest("POST", "http://localhost:3000/api/chat/stream", bytes.NewReader(body)) if err != nil { return "", err } req.Header.Set("Content-Type", "application/json") req.Header.Set("Authorization", "Bearer "+token) req.Header.Set("Accept", "text/event-stream") resp, err := http.DefaultClient.Do(req) if err != nil { return "", err } defer resp.Body.Close() var fullResponse strings.Builder scanner := bufio.NewScanner(resp.Body) for scanner.Scan() { line := scanner.Text() if strings.HasPrefix(line, "data: ") { chunk := line[6:] fmt.Print(chunk) fullResponse.WriteString(chunk) } } return fullResponse.String(), scanner.Err()
} func main() { result, err := streamChat("Explain how neural networks learn", "eyJhbGciOi...") if err != nil { panic(err) } fmt.Printf("\n\nFull response length: %d characters\n", len(result))
}

